declare(strict_types=1);

/**
 * lote17.php — Cargo e idioma en cada contacto del transportista.
 *
 * REQUIERE los lotes 15 y 16 aplicados.
 *
 * Qué instala:
 *   • Dos columnas en `carrier_contacts`: `position` y `preferred_locale`, las
 *     dos NOT NULL con valor por omisión y con su CHECK. Las filas que ya
 *     existan quedan en `other` / `en`, que es exactamente lo que se sabía de
 *     ellas.
 *   • `App\Enums\CarrierContactPosition`: dueño, despacho, seguridad,
 *     cumplimiento, facturación, jefe de conductores, taller, fuera de horario
 *     y otro. Lista cerrada, como la de factoring y por lo mismo: con texto
 *     libre acaban conviviendo «dispatch», «Despacho» y «OPS».
 *   • Los dos desplegables en cada fila de la lista de contactos.
 *   • EL SELECTOR DE IDIOMA DE EMPRESA DESAPARECE del formulario.
 *     `carriers.preferred_locale` pasa a ser el espejo del idioma del contacto
 *     PRINCIPAL, igual que ya lo era su nombre, su correo y su teléfono. Tener
 *     dos controles —uno de empresa y otro por persona— garantizaba que un día
 *     dijeran cosas distintas y nadie supiera cuál manda.
 *   • 4 pruebas Pest nuevas; las 10 del lote 15 actualizadas.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote17.php            # aplica
 *     php lote17.php --dry-run  # dice qué haría y no toca nada
 *
 * Es idempotente: un trozo ya aplicado se salta. Si un fichero no está donde
 * este guion espera, ABORTA sin escribir nada — no adivina.
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);

$hechos = [];
$saltados = [];
$errores = [];

function ruta(string $rel): string
{
    global $raiz;

    return $raiz.DIRECTORY_SEPARATOR.$rel;
}

/** Escribe un fichero nuevo (o lo deja igual si ya tiene ese contenido). */
function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;

    $destino = ruta($rel);

    if (is_file($destino) && file_get_contents($destino) === $contenido) {
        $saltados[] = "= {$rel}";

        return;
    }

    $existia = is_file($destino);

    if ($dry) {
        $hechos[] = ($existia ? '~ ' : '+ ').$rel;

        return;
    }

    $dir = dirname($destino);

    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) {
        $errores[] = "no se pudo crear el directorio {$dir}";

        return;
    }

    if (file_put_contents($destino, $contenido) === false) {
        $errores[] = "no se pudo escribir {$rel}";

        return;
    }

    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados sobre un fichero existente.
 *
 * Para cada par: si el resultado YA está, se salta; si el texto de partida está
 * una sola vez, se sustituye; en cualquier otro caso, se aborta el fichero
 * entero sin escribir. Un anclaje que no encaja significa que el fichero no es
 * el que este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;

    $destino = ruta($rel);

    if (! is_file($destino)) {
        $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?";

        return;
    }

    $texto = file_get_contents($destino);
    $aplicados = 0;
    $yaEstaban = 0;

    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) {
            $yaEstaban++;

            continue;
        }

        $veces = substr_count($texto, $antes);

        if ($veces !== 1) {
            $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero.";

            return;
        }

        $texto = str_replace($antes, $despues, $texto);
        $aplicados++;
    }

    if ($aplicados === 0) {
        $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)";

        return;
    }

    if ($dry) {
        $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";

        return;
    }

    if (file_put_contents($destino, $texto) === false) {
        $errores[] = "no se pudo escribir {$rel}";

        return;
    }

    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

// Comprobación mínima de que estamos donde toca.
foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

